solution.javascript:
function buscarRango(nums, objetivo) {
  const limiteInferior = (x) => {
    let lo = 0, hi = nums.length;
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (nums[mid] < x) lo = mid + 1; else hi = mid;
    }
    return lo;
  };
  const primero = limiteInferior(objetivo);
  if (primero === nums.length || nums[primero] !== objetivo) return [-1, -1];
  return [primero, limiteInferior(objetivo + 1) - 1];
}

solution.python:
from bisect import bisect_left, bisect_right

def buscarRango(nums, objetivo):
    i = bisect_left(nums, objetivo)
    if i == len(nums) or nums[i] != objetivo:
        return [-1, -1]
    return [i, bisect_right(nums, objetivo) - 1]
